"""Canonical taxonomy for independent work and flexible employment."""
DOMAINS=tuple({"domain_id":r[0],"name":r[1],"description":r[2]} for r in [["ai_automation","AI Automation","AI-assisted operations, agents, integrations and workflow automation."],["app_development","App Development","Native, mobile, desktop and cross-platform applications."],["bookkeeping_accounting","Bookkeeping and Accounting","Bookkeeping, reconciliation, invoicing and accounting support within local rules."],["business_consulting","Business Consulting","Strategy, research, process improvement and business advisory."],["coaching_training","Coaching and Training","Professional coaching, mentoring, workshops and skills development."],["creative_commissions","Creative Commissions","Custom illustration, creative commissions, crafts and digital assets."],["data_analysis","Data Analysis","Data cleaning, dashboards, statistical analysis and business intelligence."],["delivery_gig_work","Delivery Gig Work","Food, parcel, grocery, courier and last-mile delivery."],["digital_marketing","Digital Marketing","Campaigns, paid media, email marketing, funnels and growth."],["driving_transport_gigs","Driving and Transport Gigs","Passenger transport, commercial driving, fleet and logistics work."],["graphic_design","Graphic Design","Branding, layouts, presentations, packaging and visual design."],["home_service_gigs","Home Service Gigs","Cleaning, repairs, installation, maintenance and local field services."],["jobs_careers_employment_core_ecosystem","Jobs Careers and Employment","Employment discovery, career pathways, recruitment and workforce services."],["legal_consulting","Legal Consulting","Legal research and licensed legal services subject to jurisdictional authorization."],["microtasks","Microtasks","Small scoped digital tasks, annotation, surveys, moderation and crowdwork."],["photography","Photography","Portrait, product, event, commercial and editorial photography."],["professional_contracting","Professional Contracting","Independent contracts, specialist delivery and B2B subcontracting."],["seo","Search Engine Optimization","Technical SEO, on-page, local SEO, audits and organic growth."],["social_media_management","Social Media Management","Content calendars, publishing, moderation and community management."],["software_engineering","Software Engineering","Backend, frontend, APIs, cloud, DevOps, QA and security engineering."],["translation_localization","Translation and Localization","Translation, interpretation, subtitling and multilingual QA."],["tutoring","Tutoring","One-to-one tutoring, exam preparation, academic support and instruction."],["video_audio_production","Video and Audio Production","Video editing, sound design, podcasting and multimedia production."],["virtual_assistance","Virtual Assistance","Remote administration, scheduling, research and executive assistance."],["web_development","Web Development","Websites, CMS, e-commerce, web apps, accessibility and integrations."],["writing_editing","Writing and Editing","Copywriting, technical writing, editing, proofreading and documentation."],["remote_employment","Remote Employment","Distributed employee roles and fully remote work."],["hybrid_employment","Hybrid Employment","Roles combining remote work and on-site attendance."],["work_from_home","Work From Home","Home-based employment, independent work and service delivery."],["part_time_work","Part-time Work","Reduced-hours employment, flexible shifts and part-time engagements."],["full_time_work","Full-time Work","Full-time employment and sustained independent engagements."],["freelance_marketplaces","Freelance Marketplaces","Client discovery, proposals, portfolios, platform rules and marketplace models."],["independent_businesses","Independent Businesses","Self-employment, solo businesses, micro-enterprises and independent studios."],["project_management","Project Management","Scoping, estimation, milestones, delivery assurance and handover."],["sales_customer_support","Sales and Customer Support","Lead generation, customer success, helpdesk and customer experience."],["ecommerce_operations","E-commerce Operations","Store operations, catalog management, order support and marketplace operations."],["cybersecurity_it_support","Cybersecurity and IT Support","IT helpdesk, systems support and authorized security operations."],["research_knowledge_services","Research and Knowledge Services","Desk research, literature scans, data gathering and fact-checking."],["content_community_moderation","Content and Community Moderation","Content review, community moderation and policy-based escalation."],["testing_quality_assurance","Testing and Quality Assurance","Manual testing, usability testing, software QA and test automation."],["supply_chain_logistics","Supply Chain and Logistics","Procurement, inventory, dispatch and logistics planning."],["events_experiential_services","Events and Experiential Services","Event staffing, planning and production coordination."],["care_personal_support","Care and Personal Support","Non-clinical personal support subject to local safeguarding and licensing."],["repair_maintenance_technical","Repair and Maintenance","Appliance, equipment, device and facility maintenance."],["education_training_services","Education and Training Services","Independent instruction, course creation and training delivery."],["real_estate_property_services","Real Estate and Property Services","Property photography, listing support and licensed brokerage where required."],["financial_professional_services","Financial Professional Services","Financial analysis and authorized professional support within local rules."],["compliance_risk_services","Compliance and Risk Services","Policy documentation, risk registers, compliance support and audit preparation."],["design_product_ux","Product and UX Design","User research, UX/UI design, prototyping and service design."],["ai_data_annotation","AI Data Annotation","Data labeling, model evaluation and AI quality workflows with privacy safeguards."],["sales_partnerships","Sales and Partnerships","Prospecting, partnerships, account development and proposal support."]])
def list_domains(): return [dict(x) for x in DOMAINS]
def get_domain(domain_id):
 key=domain_id.strip().casefold()
 item=next((x for x in DOMAINS if x["domain_id"]==key),None)
 return None if item is None else dict(item)
def search_domains(keyword):
 term=keyword.strip().casefold()
 return [] if not term else [dict(x) for x in DOMAINS if term in x["domain_id"].casefold() or term in x["name"].casefold() or term in x["description"].casefold()]
